"""Postfix to Infix — stack of partial expressions.

Each operator pops two finished expressions and pushes "(left op right)".

Time: O(n)   Space: O(n)
"""


class Solution:
    def postfixToInfix(self, s: str) -> str:
        stack = []
        for ch in s:
            if ch.isalnum():
                stack.append(ch)
            else:
                right, left = stack.pop(), stack.pop()
                stack.append("(%s%s%s)" % (left, ch, right))
        return stack[-1]
